import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")
    with open(file_path, 'r') as f:
        import yaml
        data = yaml.load(f, Loader=yaml.Loader)
    required_fields = INPUT_JSON["required"]
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")
    properties = INPUT_JSON["properties"]
    for key, value in properties.items():
        if key in data:
            expected_type = value["type"]
            if not isinstance(data[key], expected_type):
                raise ValueError(f"Type mismatch for attribute {key}")
    if "email" in data:
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError("Invalid email format")
    if attribute not in data:
        raise ValueError(f"Attribute {attribute} not found")
    return data[attribute]

